def s3(self):
    required_fields = {
        'static-bucket-name': 'BucketName'
    }
    present_keys = self.data['s3'].keys()
    for i in required_fields.keys():
        if i not in present_keys:
            print "\n\n[ERROR] Missing S3 fields [%s]" % i
            sys.exit(1)
    bucket = Bucket(
        "StaticBucket",
        AccessControl="BucketOwnerFullControl",
        BucketName=self.data['s3']['static-bucket-name'],
    )
    if 'policy' in present_keys:
        policy = json.loads(open(self.data['s3']['policy']).read())
    else:
        arn = 'arn:aws:s3:::%s/*' % self.data['s3']['static-bucket-name']
        policy = {
            'Action': ['s3:GetObject'],
            'Resource': arn,
            'Effect': 'Allow',
            'Principal': '*'}
    bucket_policy = BucketPolicy(
        "StaticBucketPolicy",
        Bucket=Ref(bucket),
        PolicyDocument={"Statement": [policy]},
    )
    resources = [bucket, bucket_policy]
    return resources

def insert(self, d, update_duplicates=True):
    result = self.collection.find_one({'dir_name': d['dir_name']}, ['dir_name', 'task_id'])
    if result is None or update_duplicates:
        d['last_updated'] = datetime.datetime.today()
        if result is None:
            if 'task_id' not in d or not d['task_id']:
                d['task_id'] = self.db.counter.find_and_modify(query={'_id': 'taskid'}, update={'$inc': {'c': 1}})['c']
            logger.info('Inserting {} with taskid = {}'.format(d['dir_name'], d['task_id']))
        elif update_duplicates:
            d['task_id'] = result['task_id']
            logger.info('Updating {} with taskid = {}'.format(d['dir_name'], d['task_id']))
        self.collection.update({'dir_name': d['dir_name']}, {'$set': d}, upsert=True)
        return d['task_id']
    else:
        logger.info('Skipping duplicate {}'.format(d['dir_name']))
        return None

