def extract_tar(archive, compression, cmd, **kwargs):
    verbose = kwargs['verbose']
    outdir = kwargs['outdir']
    if verbose:
        util.log_info('extracting %s...' % archive)
    tfile = tarfile.open(archive)
    try:
        tfile.extractall(path=outdir)
    finally:
        tfile.close()
    if verbose:
        util.log_info('... extracted to %s' % outdir)
    return None

class ConfigError(Exception):
    pass

def get_config(config_path=None):
    if config_path is None:
        config_path = _find_configuration_file()
    logger.debug('using the config file at {}'.format(config_path))
    config = ConfigObj(DEFAULTSPATH, interpolation=False)
    try:
        user_config = ConfigObj(config_path, configspec=SPECPATH, interpolation=False, file_error=True)
    except ConfigObjError as error:
        logger.fatal('parsing the config file file with the following error: {}'.format(error))
        logger.fatal('if you recently updated khal, the config file format might have changed, in that case please consult the CHANGELOG or other documentation')
        sys.exit(1)
    fdict = {'timezone': is_timezone, 'expand_path': expand_path}
    validator = Validator(fdict)
    results = user_config.validate(validator, preserve_errors=True)
    if not results:
        for entry in flatten_errors(config, results):
            (section_list, key, error) = entry
            if key is not None:
                section_list.append(key)
            else:
                section_list.append('[missing section]')
            section_string = ', '.join(section_list)
            if error is False:
                error = 'Missing value or section.'
            print(section_string, ' = ', error)
        raise ConfigError('Configuration validation failed.')
    config.merge(user_config)
    config_checks(config)
    extras = get_extra_values(user_config)
    for (section, value) in extras:
        if section == ():
            logger.warn('unknown section "{}" in config file'.format(value))
        else:
            section = sectionize(section)
            logger.warn('unknown key or subsection "{}" in section "{}"'.format(value, section))
    return config

async def get_difference(self):
    pts_date = self.update._pts_date
    if not isinstance(pts_date, tuple):
        return
    (pts, date) = pts_date
    if not pts:
        return
    if not date:
        date = 1
    self.client._log[__name__].debug('Getting difference for entities')
    result = await self.client(functions.updates.GetDifferenceRequest(pts - 1, date, 0))
    if isinstance(result, (types.updates.Difference, types.updates.DifferenceSlice)):
        self.update._entities.update({utils.get_peer_id(x): x for x in itertools.chain(result.users, result.chats)})

