            if job_name_a:
                self._changed_nodes[job_name_b] = job_name_a
    self._new_nodes = self._unresolved_b_nodes
    self._deleted_nodes = self._unresolved_a_nodes
    self._unresolved_a_nodes = set()
    self._unresolved_b_nodes = set()

