def export(request):
    stripe.api_key = settings.STRIPE_SECRET_KEY

    def unique(seq, idfun=None):
        if idfun is None:

            def idfun(x):
                return x
        seen = {}
        result = []
        for item in seq:
            marker = idfun(item)
            if marker in seen:
                continue
            seen[marker] = 1
            result.append(item)
        return result
    offset = request.POST.get('offset', 0)
    delimiter = request.POST.get('delimiter', ',')
    count = request.POST.get('count', 100)
    date_from = request.POST.get('date_from')
    date_to = request.POST.get('date_to')
    if date_from:
        date_from = datetime.datetime.strptime(date_from, '%Y-%m-%d')
    else:
        date_from = datetime.datetime.now() - datetime.timedelta(days=1)
    if date_to:
        date_to = datetime.datetime.strptime(date_to, '%Y-%m-%d')
    else:
        date_to = datetime.datetime.now()
    created = {'gte': date_from.strftime('%s'), 'lte': date_to.strftime('%s')}
    all_charges = []
    charges_left = True
    while charges_left:
        charges = stripe.Charge.all(count=count, offset=offset, created=created)['data']
        if len(charges):
            all_charges += charges
            offset = offset + count
        else:
            charges_left = False
    all_charges = unique(all_charges, lambda c: c['id'])
    all_charges = [dict(zip(ch.keys(), ch.values())) for ch in all_charges]
    fieldnames = set()
    for charge in all_charges:
        for field in ['metadata', 'card']:
            if field in charge:
                for (key, value) in charge[field].items():
                    if not key.startswith('exp_'):
                        charge['%s__%s' % (field, key)] = value
        for field in ['metadata', 'previous_metadata', 'card']:
            if field in charge:
                del charge[field]
        charge['amount'] = int(charge['amount']) / Decimal(100)
        charge['amount_gift_aid'] = (charge['amount'] * Decimal(0.2)).quantize(Decimal(10) ** (-2))
        fieldnames |= set(charge.keys())
    fieldnames = sorted(list(fieldnames))
    response = HttpResponse(content_type='text/csv')
    filename = 'rca-donations-%s--%s.csv' % (date_from.strftime('%Y-%m-%d-%H:%M'), date_to.strftime('%Y-%m-%d-%H:%M'))
    response['Content-Disposition'] = 'attachment; filename="%s"' % filename
    writer = UnicodeWriter(response, delimiter=delimiter, quotechar='"', quoting=csv.QUOTE_MINIMAL)
    writer.writerow(fieldnames)
    for charge in all_charges:
        data = [unicode(charge[f] if f in charge else '') for f in fieldnames]
        writer.writerow(data)
    return response

def _metadata_column_factory(self, series):
    dtype = series.dtype
    if NumericMetadataColumn._is_supported_dtype(dtype):
        column = NumericMetadataColumn(series)
    elif CategoricalMetadataColumn._is_supported_dtype(dtype):
        column = CategoricalMetadataColumn(series)
    elif dtype == 'bool':
        raise TypeError('Metadata column %r has an unsupported pandas dtype %r' % (series.name, dtype))
    else:
        raise TypeError('Metadata column %r has an unsupported pandas dtype %r' % (series.name, dtype))
    column._add_artifacts(self.artifacts)
    return column

def main():
    args = parse_args()
    assert args.out or args.eval or args.format_only or args.show\
        or args.show_dir,\
        ('Please specify at least one operation (save/eval/format/show the '\
         'results / save the results) with the argument "--out", "--eval"'\
         ', "--format-only", "--show" or "--show-dir")
    if args.eval and args.format_only:
        raise ValueError('--eval and --format_only cannot be both specified')
    if args.out is not None and not args.out.endswith(('.pkl', '.pickle')):
        raise ValueError('The output file must be a pkl file.')
    cfg = Config.fromfile(args.config)
    if args.cfg_options is not None:
        cfg.merge_from_dict(args.cfg_options)
    if cfg.get('cudnn_benchmark', False):
        torch.backends.cudnn.benchmark = True
    cfg.model.pretrained = None
    necks = cfg.model.get('neck')
    if necks:
        necks = necks if isinstance(necks, list) else [necks]
        for neck in necks:
            if neck.get('rfp_backbone'):
                if neck.rfp_backbone.get('pretrained'):
                    neck.rfp_backbone.pretrained = None
    cfg.data.test.test_mode = True
    if args.launcher == 'none':
        distributed = False
    else:
        distributed = True
        init_dist(args.launcher, **cfg.dist_params)
    dataset = build_dataset(cfg.data.test)
    data_loader = build_dataloader(
        dataset,
        samples_per_gpu=2,
        workers_per_gpu=cfg.data.workers_per_gpu,
        dist=distributed,
        shuffle=False)
    model = build_detector(cfg.model, train_cfg=None, test_cfg=cfg.test_cfg)
    fp16_cfg = cfg.get('fp16', None)
    if fp16_cfg is not None:
        wrap_fp16_model(model)
    checkpoint = load_checkpoint(model, args.checkpoint, map_location='cpu')
    classes_rearrange = cfg.get('classes_rearrange', False)
    if classes_rearrange:
        model = rearrange_classes(model, cfg.classes, cfg.dataset_type)
    if args.fuse_conv_bn:
        model = fuse_module(model)
    if 'CLASSES' in checkpoint['meta']:
        model.CLASSES = checkpoint['meta']['CLASSES']
    else:
        model.CLASSES = dataset.CLASSES
    if not distributed:
        model = MMDataParallel(model, device_ids=[0])
        outputs = single_gpu_test(model, data_loader, args.show, args.show_dir,
                                  args.show_score_thr)
    else:
        model = MMDistributedDataParallel(
            model.cuda(),
            device_ids=[torch.cuda.current_device()],
            broadcast_buffers=False)
        outputs = multi_gpu_test(model, data_loader, args.tmpdir,
                                 args.gpu_collect)
    rank, _ = get_dist_info()
    if rank == 0:
        if args.out:
            print(f'\nwriting results to {args.out}')
            mmcv.dump(outputs, args.out)
        kwargs = {} if args.options is None else args.options
        if args.format_only:
            dataset.format_results(outputs, **kwargs)
        if args.eval:
            dataset.evaluate(outputs, args.eval, **kwargs)

def get_column_differences(self, expected_columns: Mapping[str, ColumnType]) -> List[str]:
    errors: List[str] = []
    for (column_name, column) in expected_columns.items():
        if column_name not in self.get_columns():
            errors.append("Column '%s' exists in local ClickHouse but not in schema!" % column_name)
            continue
        expected_type = self.get_columns()[column_name].type
        if isinstance(expected_type, ReadOnly):
            expected_type = expected_type.inner_type
        if column != expected_type:
            while isinstance(column, ColumnTypeWithModifier):
                column = column.inner_type
            if column != expected_type:
                errors.append("Column '%s' type differs between local ClickHouse and schema! (expected: %s, is: %s)" % (column_name, expected_type, column))
    return errors

def fetch_proteins(self):
    _records = [_rec for (_accession, _rec) in self.dbbuddy.records.items() if _rec.database == 'uniprot' and (not _rec.record)]
    if len(_records) > 0:
        _stderr('Retrieving %s full records from UniProt...\n' % len(_records))
        _ids = ','.join([_rec.accession for _rec in _records])
        request = Request('%s?query=%s&format=txt' % (self.server, _ids))
        response = urlopen(request)
        data = SeqIO.to_dict(SeqIO.parse(response, 'swiss'))
        for _rec in _records:
            if _rec.accession not in data:
                self.dbbuddy.failures.append(_rec.accession)
            else:
                self.dbbuddy.records[_rec.accession].record = data[_rec.accession]

def sub_sections(self, chunk_size: int=16) -> Generator[Tuple[Tuple[int, int], SelectionBox], None, None]:
    boxes = []
    for box in self.subboxes:
        boxes.extend(box.sub_sections(chunk_size))
    yield from boxes

