def log_request(self, bytes):
    reply_code = 200
    if self.env.has_key('PATH_INFO'):
        path = '%s%s' % (self.server.module, self.env['PATH_INFO'])
    else:
        path = '%s/' % self.server.module
    if self.env.has_key('REQUEST_METHOD'):
        method = self.env['REQUEST_METHOD']
    else:
        method = 'GET'
    if self.addr:
        self.server.logger.log(self.addr[0], '%d - - [%s] "%s %s" %d %d' % (self.addr[1], time.strftime('%d/%b/%Y:%H:%M:%S ', time.gmtime(time.time())) + tz_for_log, method, path, bytes, reply_code))
    else:
        self.server.logger.log('127.0.0.1', '- - [%s] "%s %s" %d %d' % (time.strftime('%d/%b/%Y:%H:%M:%S ', time.gmtime(time.time())) + tz_for_log, method, path, bytes, reply_code))

def do_win(session):
    session.speed_pause()
    show_db_message(session, 'YOU_HAVE_WON')
    horizons.main.fife.play_sound('effects', 'content/audio/sounds/events/szenario/win.ogg')
    continue_playing = False
    if session.campaign is None or not AUTO_CONTINUE_CAMPAIGN:
        continue_playing = session.gui.show_popup(_('You have won!'), _('You have completed this scenario. ' + 'Do you want to continue playing?'), show_cancel_button=True)
    if not continue_playing:
        if session.campaign:
            SavegameManager.mark_scenario_as_won(session.campaign)
            ExtScheduler().add_new_object(Callback(SavegameManager.load_next_scenario, session.campaign), SavegameManager, run_in=1)
        else:
            Scheduler().add_new_object(Callback(session.gui.quit_session, force=True), session, run_in=0)
    else:
        session.speed_unpause()

