def __getattr__(self, key):
    if (key == 'value' and 'value' not in self.data or (key == 'type' and 'type' not in self.data)) and hasattr(self, 'save_as_artifact'):
        with tempfile.TemporaryDirectory() as tmpdir:
            try:
                download_artifact(self, path=tmpdir)
                fs = os.listdir(tmpdir)
                assert len(fs) == 1
                with open(os.path.join(tmpdir, fs[0]), 'r') as f:
                    content = jsonpickle.loads(f.read())
                    self.value = content
                    if isinstance(content, dict) and 'value' in content:
                        if 'type' in content:
                            self.type = content['type']
                        if 'type' in content and content['type'] != str(str):
                            self.value = jsonpickle.loads(content['value'])
                        else:
                            self.value = content['value']
            except Exception as e:
                logger.warning('Failed to load parameter value from artifact: %s' % e)
    if key == 'value' and hasattr(self, 'description') and (self.description is not None):
        desc = jsonpickle.loads(self.description)
        if desc['type'] != str(str):
            try:
                return jsonpickle.loads(super().__getattr__('value'))
            except Exception as e:
                logger.warning('Failed to unpickle parameter: %s' % e)
    return super().__getattr__(key)

def _crawl(self, key_path, env_vars):
    new_vars = {}
    obj = self._path_get(key_path)
    if hasattr(obj, 'keys') and hasattr(obj, '__getitem__'):
        for key in obj.keys():
            merged_vars = dict(env_vars, **new_vars)
            merged_path = key_path + [key]
            if self._to_env_var(merged_path) in merged_vars:
                raise ValueError(f'Conflict detected for {merged_path}')
            crawled = self._crawl(merged_path, merged_vars)
            new_vars.update(crawled)
    else:
        new_vars[self._to_env_var(key_path)] = key_path
    return new_vars

def _setObject(self, id, object, roles=None, user=None):
    v = self._checkId(id)
    if v is not None:
        id = v
    try:
        t = object.meta_type
    except:
        t = None
    self._objects = self._objects + ({'id': id, 'meta_type': t},)
    self._setOb(id, object)
    have = self.__dict__.has_key
    if have('__allow_groups__') and (not have('acl_users')):
        delattr(self, '__allow_groups__')
    return id

def can_be_main_file(directory_entry: typing.Any, project: typing.Any) -> bool:
    if not isinstance(directory_entry, DirectoryListEntry):
        return False
    directory_entry = typing.cast(DirectoryListEntry, directory_entry)
    if not isinstance(project, Project):
        return False
    project = typing.cast(Project, project)
    if directory_entry.is_directory:
        return False
    return not is_main_file(directory_entry, project)

async def from_id(cls, client: Client, channel_id: int) -> Channel:
